+#define  FDTX_GOOD			BIT(15)
+#define  BUS_STATE1			BIT(16)
+#define  BUS_STATE2			BIT(17)
+#define  PANICS				BIT(26)
+#define BASE_ADDRESS			0x490
+#define NUMBER_OF_PAIRS			0x494
+#define WATCHDOG_LIMIT			0x498
+#define SELF_ADDRESS			0x49c
