+
+	rec->rec_phys = virt_to_phys(rec->rec_page);
+	rec->run_phys = virt_to_phys(rec->run);
+
+	if (rmi_delegate_page(rec->rec_phys)) {
+		r = -ENXIO;
+		goto out_free_pages;
+	}
+
+	params->mpidr = mpidr;
+
