+	chained_irq_enter(chip, desc);
+	val = readl(spmi->regs + SPMI_IRQ_ACK_BASE + (SPMI_IRQ_FIFO_RX / 32) * 4);
+	if (val & BIT(SPMI_IRQ_FIFO_RX % 32)) {
